(function () {
  'use strict';

  var WA = '5548988677137';
  var TAXA = 0.0189; // taxa de referência ao mês (só para simulação)
  var PASSO = window.matchMedia && window.matchMedia('(max-width: 639px)').matches ? 6 : 9;

  var $ = function (s, el) { return (el || document).querySelector(s); };
  var $$ = function (s, el) { return Array.prototype.slice.call((el || document).querySelectorAll(s)); };
  var brl = function (n) { return 'R$ ' + Math.round(n).toLocaleString('pt-BR'); };
  var brl2 = function (n) { return n.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }); };
  var km = function (n) { return n.toLocaleString('pt-BR') + ' km'; };
  var esc = function (s) { return String(s).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); };
  var norm = function (s) { return String(s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase(); };
  var waLink = function (msg, fone) { return 'https://wa.me/' + (fone || WA) + '?text=' + encodeURIComponent(msg); };
  var nome = function (c) { return c.marca + ' ' + c.modelo; };
  var nomeCompleto = function (c) { return c.marca + ' ' + c.modelo + ' ' + c.versao.replace(/ · /g, ' ') + ' ' + c.ano; };
  var foto = function (c, i) { return 'assets/img/carros/' + c.id + '-' + i + '.webp'; };
  var porId = {};
  ESTOQUE.forEach(function (c) { porId[c.id] = c; });

  /* ---------- Links de WhatsApp com mensagem pronta ---------- */
  $$('a[data-wa]').forEach(function (a) {
    var m = a.getAttribute('href').match(/wa\.me\/(\d+)/);
    a.href = waLink(a.getAttribute('data-wa'), m ? m[1] : WA);
  });

  /* ---------- Topo ---------- */
  var topo = $('#topo');
  var nav = $('#nav');
  var menuBtn = $('#menuBtn');
  var onScroll = function () { topo.classList.toggle('is-scrolled', window.scrollY > 8); };
  window.addEventListener('scroll', onScroll, { passive: true });
  onScroll();
  var fecharMenu = function () {
    nav.classList.remove('is-open');
    menuBtn.setAttribute('aria-expanded', 'false');
    menuBtn.setAttribute('aria-label', 'Abrir menu');
  };
  menuBtn.addEventListener('click', function () {
    var aberto = nav.classList.toggle('is-open');
    menuBtn.setAttribute('aria-expanded', String(aberto));
    menuBtn.setAttribute('aria-label', aberto ? 'Fechar menu' : 'Abrir menu');
  });
  $$('a', nav).forEach(function (a) { a.addEventListener('click', fecharMenu); });
  document.addEventListener('click', function (e) {
    if (nav.classList.contains('is-open') && !nav.contains(e.target) && !menuBtn.contains(e.target)) fecharMenu();
  });
  document.addEventListener('keydown', function (e) { if (e.key === 'Escape') fecharMenu(); });

  /* ---------- Números e marcas ---------- */
  var marcas = {};
  ESTOQUE.forEach(function (c) { marcas[c.marca] = (marcas[c.marca] || 0) + 1; });
  var listaMarcas = Object.keys(marcas).sort(function (a, b) { return a.localeCompare(b, 'pt-BR'); });
  $$('[data-count-cars]').forEach(function (el) { el.textContent = ESTOQUE.length; });
  $$('[data-count-brands]').forEach(function (el) { el.textContent = listaMarcas.length; });

  var track = $('#marcasTrack');
  if (track) {
    var porQtd = listaMarcas.slice().sort(function (a, b) { return marcas[b] - marcas[a]; });
    var html = porQtd.map(function (m) { return '<span>' + esc(m) + '</span>'; }).join('');
    track.innerHTML = html + html.replace(/<span>/g, '<span aria-hidden="true">');
  }

  var fMarca = $('#fMarca');
  listaMarcas.forEach(function (m) {
    var o = document.createElement('option');
    o.value = m;
    o.textContent = m + ' (' + marcas[m] + ')';
    fMarca.appendChild(o);
  });

  /* ---------- Estoque ---------- */
  var grid = $('#gridCarros');
  var vazio = $('#vazio');
  var resultado = $('#resultado');
  var btnMais = $('#btnMais');
  var estado = { q: '', marca: '', preco: '', ordem: '', cat: '', limite: PASSO };

  function etiquetas(c) {
    var t = [];
    var has = function (x) { return c.tags.indexOf(x) > -1; };
    if (has('Novo')) t.push(['Novo', 'y']);
    if (has('Híbrido')) t.push(['Híbrido', 'y']);
    if (has('Diesel') && has('4x4')) t.push(['Diesel 4x4', '']);
    else if (has('Diesel')) t.push(['Diesel', '']);
    else if (has('4x4')) t.push(['4x4', '']);
    if (has('7 lugares')) t.push(['7 lugares', '']);
    if (has('Único dono')) t.push(['Único dono', '']);
    return t.slice(0, 2);
  }

  function msgCarro(c) {
    return 'Olá, Podium! Tenho interesse no ' + nomeCompleto(c) + ', anunciado por ' + brl(c.preco) + ' no site. Ainda está disponível?';
  }

  function altCarro(c, i) {
    var lugar = i === 0 ? 'na frente da Podium Multimarcas' : (i === 1 ? 'no pátio coberto da loja' : 'vista interna');
    return nome(c) + ' ' + c.versao.replace(/ · /g, ' ') + ' ' + c.ano + ', cor ' + c.cor.toLowerCase() + ', ' + lugar;
  }

  function card(c) {
    var tags = etiquetas(c).map(function (t) { return '<span class="tag' + (t[1] ? ' tag--y' : '') + '">' + esc(t[0]) + '</span>'; }).join('');
    return '' +
      '<article class="carro">' +
        '<button class="carro__foto" type="button" data-open="' + c.id + '" aria-label="Ver fotos e detalhes: ' + esc(nome(c) + ' ' + c.ano) + '">' +
          '<img src="' + foto(c, 0) + '" width="800" height="450" loading="lazy" decoding="async" alt="' + esc(altCarro(c, 0)) + '">' +
          (tags ? '<span class="carro__tags">' + tags + '</span>' : '') +
          '<span class="carro__nfotos"><svg class="ico" aria-hidden="true"><use href="#i-camera"/></svg>' + c.fotos + ' fotos</span>' +
        '</button>' +
        '<div class="carro__corpo">' +
          '<p class="carro__marca">' + esc(c.marca) + '</p>' +
          '<h3 class="carro__nome">' + esc(c.modelo) + '</h3>' +
          '<p class="carro__versao" title="' + esc(c.versao) + '">' + esc(c.versao) + '</p>' +
          '<ul class="specs">' +
            '<li><svg class="ico" aria-hidden="true"><use href="#i-cal"/></svg><span class="sr">Ano: </span>' + esc(c.ano) + '</li>' +
            '<li><svg class="ico" aria-hidden="true"><use href="#i-km"/></svg><span class="sr">Quilometragem: </span>' + km(c.km) + '</li>' +
            '<li><svg class="ico" aria-hidden="true"><use href="#i-gear"/></svg><span class="sr">Câmbio: </span>' + esc(c.cambio) + '</li>' +
            '<li><svg class="ico" aria-hidden="true"><use href="#i-fuel"/></svg><span class="sr">Combustível: </span>' + esc(c.comb) + '</li>' +
          '</ul>' +
          '<p class="carro__preco"><strong>' + brl(c.preco) + '</strong><small>à vista</small></p>' +
          '<div class="carro__acoes">' +
            '<a class="btn btn--y" href="' + waLink(msgCarro(c)) + '" target="_blank" rel="noopener"><svg class="ico" aria-hidden="true"><use href="#i-wa"/></svg>Tenho interesse</a>' +
            '<button class="btn btn--line" type="button" data-open="' + c.id + '">Detalhes</button>' +
          '</div>' +
        '</div>' +
      '</article>';
  }

  function filtrar() {
    var termos = norm(estado.q).split(/\s+/).filter(Boolean);
    var faixa = estado.preco ? estado.preco.split('-').map(Number) : null;
    var lista = ESTOQUE.filter(function (c) {
      if (estado.marca && c.marca !== estado.marca) return false;
      if (faixa && (c.preco < faixa[0] || c.preco > faixa[1])) return false;
      if (estado.cat) {
        if (estado.cat === 'Híbrido' || estado.cat === 'Diesel') { if (c.comb !== estado.cat) return false; }
        else if (c.cat !== estado.cat) return false;
      }
      if (termos.length) {
        var alvo = norm([c.marca, c.modelo, c.versao, c.ano, c.cor, c.comb, c.cat, c.cambio].join(' '));
        for (var i = 0; i < termos.length; i++) if (alvo.indexOf(termos[i]) === -1) return false;
      }
      return true;
    });
    var ord = {
      'preco-asc': function (a, b) { return a.preco - b.preco; },
      'preco-desc': function (a, b) { return b.preco - a.preco; },
      'ano-desc': function (a, b) { return b.anoMod - a.anoMod || a.km - b.km; },
      'km-asc': function (a, b) { return a.km - b.km; }
    }[estado.ordem];
    if (ord) lista = lista.slice().sort(ord);
    return lista;
  }

  function render() {
    var lista = filtrar();
    var mostra = lista.slice(0, estado.limite);
    grid.innerHTML = mostra.map(card).join('');
    vazio.hidden = lista.length > 0;
    btnMais.parentNode.hidden = lista.length <= estado.limite;
    var resta = lista.length - mostra.length;
    btnMais.textContent = 'Ver mais ' + Math.min(resta, PASSO) + (resta === 1 ? ' carro' : ' carros') + ' (' + resta + ' restantes)';
    resultado.innerHTML = lista.length
      ? 'Mostrando <b>' + mostra.length + '</b> de <b>' + lista.length + '</b> ' + (lista.length === 1 ? 'carro' : 'carros') + (lista.length < ESTOQUE.length ? ' com esses filtros' : ' no estoque')
      : '';
  }

  var timer;
  $('#fBusca').addEventListener('input', function (e) {
    clearTimeout(timer);
    timer = setTimeout(function () { estado.q = e.target.value; estado.limite = PASSO; render(); }, 150);
  });
  fMarca.addEventListener('change', function (e) { estado.marca = e.target.value; estado.limite = PASSO; render(); });
  $('#fPreco').addEventListener('change', function (e) { estado.preco = e.target.value; estado.limite = PASSO; render(); });
  $('#fOrdem').addEventListener('change', function (e) { estado.ordem = e.target.value; estado.limite = PASSO; render(); });
  $$('#fCat .chip').forEach(function (b) {
    b.setAttribute('aria-pressed', b.classList.contains('is-on') ? 'true' : 'false');
    b.addEventListener('click', function () {
      $$('#fCat .chip').forEach(function (x) { x.classList.remove('is-on'); x.setAttribute('aria-pressed', 'false'); });
      b.classList.add('is-on');
      b.setAttribute('aria-pressed', 'true');
      estado.cat = b.getAttribute('data-cat');
      estado.limite = PASSO;
      render();
    });
  });
  btnMais.addEventListener('click', function () {
    var antes = estado.limite;
    estado.limite += PASSO;
    render();
    var novo = grid.children[antes];
    if (novo) { var f = novo.querySelector('button, a'); if (f) f.focus({ preventScroll: true }); }
  });
  render();

  /* ---------- Modal de detalhes ---------- */
  var modal = $('#modal');
  var mFoto = $('#mFoto');
  var atual = null;
  var idx = 0;
  var todosItens = false;

  function mostrarFoto(i) {
    if (!atual) return;
    idx = (i + atual.fotos) % atual.fotos;
    mFoto.src = foto(atual, idx);
    mFoto.alt = altCarro(atual, idx);
    $('#mCont').textContent = (idx + 1) + '/' + atual.fotos;
    $$('#mThumbs button').forEach(function (b, k) {
      b.classList.toggle('is-on', k === idx);
      b.setAttribute('aria-current', k === idx ? 'true' : 'false');
    });
  }

  var TOP = ['Único dono', 'Revisões em concessionária', 'Garantia de fábrica', 'Baixa quilometragem'];
  function renderItens() {
    var c = atual;
    var lim = todosItens ? c.itens.length : 12;
    $('#mItens').innerHTML = c.itens.slice(0, lim).map(function (it) {
      var top = TOP.indexOf(it) > -1;
      return '<li' + (top ? ' class="is-top"' : '') + '>' + (top ? '<svg class="ico" aria-hidden="true"><use href="#i-check"/></svg>' : '') + esc(it) + '</li>';
    }).join('');
    var mais = $('#mItensMais');
    mais.hidden = c.itens.length <= 12;
    mais.textContent = todosItens ? 'Mostrar menos' : 'Ver todos os ' + c.itens.length + ' itens';
  }

  function abrir(id, semHistorico) {
    var c = porId[id];
    if (!c) return;
    atual = c;
    todosItens = false;
    $('#mMarca').textContent = c.marca;
    $('#mTitulo').textContent = c.modelo + ' ' + c.ano;
    $('#mVersao').textContent = c.versao;
    $('#mPreco').textContent = brl(c.preco);
    var specs = [
      ['i-cal', 'Ano', c.ano], ['i-km', 'Km', km(c.km)], ['i-gear', 'Câmbio', c.cambio],
      ['i-fuel', 'Combustível', c.comb], ['i-drop', 'Cor', c.cor], ['i-door', 'Portas', c.portas + ' portas']
    ];
    $('#mSpecs').innerHTML = specs.map(function (s) {
      return '<li><svg class="ico" aria-hidden="true"><use href="#' + s[0] + '"/></svg><span><small>' + s[1] + '</small>' + esc(s[2]) + '</span></li>';
    }).join('');
    var th = '';
    for (var i = 0; i < c.fotos; i++) {
      th += '<button type="button" data-i="' + i + '" aria-label="Ver foto ' + (i + 1) + '"><img src="' + foto(c, i) + '" width="800" height="450" alt="" loading="lazy" decoding="async"></button>';
    }
    $('#mThumbs').innerHTML = th;
    renderItens();
    $('#mWa').href = waLink(msgCarro(c));
    mostrarFoto(0);
    if (!modal.open) {
      if (typeof modal.showModal === 'function') modal.showModal(); else modal.setAttribute('open', '');
      document.documentElement.style.overflow = 'hidden';
    }
    modal.scrollTop = 0;
    var info = $('.modal__info'); if (info) info.scrollTop = 0;
    if (!semHistorico && history.replaceState) history.replaceState(null, '', '#carro-' + c.id);
  }

  function fechar() {
    if (typeof modal.close === 'function' && modal.open) modal.close(); else modal.removeAttribute('open');
  }
  modal.addEventListener('close', function () {
    document.documentElement.style.overflow = '';
    if (/^#carro-/.test(location.hash) && history.replaceState) history.replaceState(null, '', location.pathname + location.search);
  });
  modal.addEventListener('click', function (e) { if (e.target === modal) fechar(); });
  $('#mFechar').addEventListener('click', fechar);
  $('#mPrev').addEventListener('click', function () { mostrarFoto(idx - 1); });
  $('#mNext').addEventListener('click', function () { mostrarFoto(idx + 1); });
  $('#mThumbs').addEventListener('click', function (e) {
    var b = e.target.closest('button[data-i]');
    if (b) mostrarFoto(Number(b.getAttribute('data-i')));
  });
  $('#mItensMais').addEventListener('click', function () { todosItens = !todosItens; renderItens(); });
  modal.addEventListener('keydown', function (e) {
    if (e.key === 'ArrowRight') mostrarFoto(idx + 1);
    if (e.key === 'ArrowLeft') mostrarFoto(idx - 1);
  });
  var x0 = null;
  var areaFoto = $('.modal__foto');
  areaFoto.addEventListener('touchstart', function (e) { x0 = e.touches[0].clientX; }, { passive: true });
  areaFoto.addEventListener('touchend', function (e) {
    if (x0 === null) return;
    var dx = e.changedTouches[0].clientX - x0;
    if (Math.abs(dx) > 40) mostrarFoto(idx + (dx < 0 ? 1 : -1));
    x0 = null;
  });

  document.addEventListener('click', function (e) {
    var b = e.target.closest('[data-open]');
    if (b) { e.preventDefault(); abrir(Number(b.getAttribute('data-open'))); }
  });

  /* ---------- Simulador ---------- */
  var sCarro = $('#sCarro');
  var sValor = $('#sValor');
  var sEntrada = $('#sEntrada');
  var prazo = 48;

  ESTOQUE.slice().sort(function (a, b) { return nome(a).localeCompare(nome(b), 'pt-BR') || b.anoMod - a.anoMod; }).forEach(function (c) {
    var o = document.createElement('option');
    o.value = c.id;
    o.textContent = nome(c) + ' ' + c.ano + ' · ' + brl(c.preco);
    sCarro.appendChild(o);
  });

  var valorNum = function () { return Number(sValor.value.replace(/\D/g, '')) || 0; };

  function calcular() {
    var v = valorNum();
    var pct = Number(sEntrada.value);
    var ent = v * pct / 100;
    var pv = Math.max(0, v - ent);
    var pmt = pv > 0 ? pv * TAXA / (1 - Math.pow(1 + TAXA, -prazo)) : 0;
    sEntrada.style.setProperty('--p', (pct / Number(sEntrada.max) * 100) + '%');
    $('#sEntradaOut').textContent = pct + '% · ' + brl(ent);
    $('#sPrazoOut').textContent = prazo + 'x';
    $('#sParcela').textContent = brl2(pmt);
    $('#sFinanciado').textContent = brl(pv);
    var c = porId[sCarro.value];
    var msg = 'Olá, Podium! Fiz uma simulação no site' + (c ? ' para o ' + nomeCompleto(c) : '') +
      ': valor de ' + brl(v) + ', entrada de ' + brl(ent) + ' e ' + prazo + 'x de ' + brl2(pmt) + ' (estimativa). Podemos conversar sobre o financiamento?';
    $('#sEnviar').href = waLink(msg);
  }

  sCarro.addEventListener('change', function () {
    var c = porId[sCarro.value];
    if (c) sValor.value = c.preco.toLocaleString('pt-BR');
    calcular();
  });
  sValor.addEventListener('input', function () {
    var n = valorNum();
    sValor.value = n ? Math.min(n, 9999999).toLocaleString('pt-BR') : '';
    var c = porId[sCarro.value];
    if (c && c.preco !== n) sCarro.value = '';
    calcular();
  });
  sEntrada.addEventListener('input', calcular);
  $$('#sPrazo .pz').forEach(function (b) {
    b.setAttribute('aria-pressed', b.classList.contains('is-on') ? 'true' : 'false');
    b.addEventListener('click', function () {
      $$('#sPrazo .pz').forEach(function (x) { x.classList.remove('is-on'); x.setAttribute('aria-pressed', 'false'); });
      b.classList.add('is-on');
      b.setAttribute('aria-pressed', 'true');
      prazo = Number(b.getAttribute('data-m'));
      calcular();
    });
  });
  calcular();

  $('#mSimular').addEventListener('click', function () {
    if (!atual) return;
    sCarro.value = String(atual.id);
    sValor.value = atual.preco.toLocaleString('pt-BR');
    calcular();
    fechar();
    document.documentElement.style.overflow = '';
    var alvo = document.getElementById('financiamento');
    if (alvo) alvo.scrollIntoView({ behavior: 'smooth', block: 'start' });
  });

  /* ---------- Diversos ---------- */
  var ano = $('#ano');
  if (ano) ano.textContent = new Date().getFullYear();

  var m = location.hash.match(/^#carro-(\d+)$/);
  if (m && porId[m[1]]) abrir(Number(m[1]), true);
})();
